// Runs when a LendLoop workflow fails after its retries. Logs the failure here and
// reports it to LendLoop, where it shows on the Admin page.
// n8n sends `execution`, or `trigger` when the failing workflow's trigger broke.
const crypto = require('crypto');

const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set on the n8n server');

const { execution, trigger, workflow = {} } = $input.first().json;
const error = execution?.error ?? trigger?.error ?? {};
const executionId = execution?.id != null ? String(execution.id) : undefined;
const report = {
  // One report per failed execution, however many times this request is retried.
  idempotencyKey: `n8n-error:${workflow.id ?? 'unknown'}:${executionId ?? Date.now()}`,
  workflowName: String(workflow.name ?? 'Unknown workflow'),
  message: String(error.message ?? 'Unknown error').slice(0, 500),
  ...(execution?.lastNodeExecuted ? { nodeName: String(execution.lastNodeExecuted) } : {}),
  ...(executionId ? { executionId } : {}),
  ...(execution?.url ? { executionUrl: String(execution.url) } : {}),
};
console.error(`[LendLoop] ${report.workflowName} failed at ${report.nodeName ?? 'its trigger'}: ${report.message}`);

const body = JSON.stringify(report);
const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return [{ json: { body, timestamp, signature } }];
